function fresh(o) { const now = Date.now(); for (const [k, t] of SEEN) if (now - t > 600e3) SEEN.delete(k); if (!o || typeof o.t !== 'number' || Math.abs(now - o.t) > 300e3 || SEEN.has(o.n)) return false; SEEN.set(o.n, now); return true; }

